const listPortfolioItems = `-- name: ListPortfolioItems :many
SELECT ordinal,source_workspace_uuid,snapshot FROM personal_portfolio_items WHERE session_id=$1 AND workspace_id=$2 AND ordinal>$3 ORDER BY ordinal LIMIT $4
`

type ListPortfolioItemsParams struct {
	SessionID    int64 `json:"session_id"`
	WorkspaceID  int64 `json:"workspace_id"`
	AfterOrdinal int64 `json:"after_ordinal"`
	RowLimit     int32 `json:"row_limit"`
}

type ListPortfolioItemsRow struct {
	Ordinal             int64     `json:"ordinal"`
	SourceWorkspaceUuid uuid.UUID `json:"source_workspace_uuid"`
	Snapshot            []byte    `json:"snapshot"`
}

func (q *Queries) ListPortfolioItems(ctx context.Context, arg ListPortfolioItemsParams) ([]ListPortfolioItemsRow, error) {
	rows, err := q.db.Query(ctx, listPortfolioItems,
		arg.SessionID,
		arg.WorkspaceID,
		arg.AfterOrdinal,
		arg.RowLimit,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ListPortfolioItemsRow{}
	for rows.Next() {
		var i ListPortfolioItemsRow
		if err := rows.Scan(&i.Ordinal, &i.SourceWorkspaceUuid, &i.Snapshot); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

